        self.pyType = _JS_UNDEFINED
        self.text = _JS_UNDEFINED
        self.yaml = _JS_UNDEFINED
        self.truthy = _JS_UNDEFINED
        self.ord = _JS_UNDEFINED
        self.tag = tag
        self.pyType = py_type
        self.text = text
        self.yaml = yaml
        self.truthy = truthy
        self.ord = ord
